const canvasHost=ref(null), modeler=ref(null), loading=ref(true), saving=ref(false), dirty=ref(false), actions=ref([]), actionKeyword=ref(''), selectedElement=ref(null), diagramRevision=ref(0), zoomLevel=ref(100)
const childMode=ref(false), childParentId=ref(''), childParentName=ref(''), mainXmlCache=ref('')
