const mainPaletteGroups=[
  {label:'主节点',items:[{name:'移动',actionKey:'MOVE'},{name:'单次取料',actionKey:'ARM.PICK'},{name:'单次放料',actionKey:'ARM.PLACE'},{name:'复合取料',actionKey:'ARM.PICK_BATCH',aliases:['ARM.BATCH_PICK']},{name:'复合放料',actionKey:'ARM.PLACE_BATCH',aliases:['ARM.BATCH_PLACE']},{name:'协作臂归零',actionKey:'ARM.HOME'},{name:'现场拍照',actionKey:'VISION.CAPTURE'}]},
  {label:'其他节点',items:[{name:'自动门',actionKey:'DOOR.OPEN'},{name:'手套箱',actionKey:'GLOVEBOX.RUN'},{name:'贴标机台',actionKey:'LABEL.RUN'},{name:'后处理机台',actionKey:'POST.RUN'}]},
]
const paletteGroups=computed(()=>{if(childMode.value)return[{label:'子节点',items:childActions}];const q=actionKeyword.value.trim().toLowerCase();return mainPaletteGroups.map(group=>({...group,items:group.items.map(item=>{const remote=actions.value.find(row=>row.actionKey===item.actionKey||item.aliases?.includes(row.actionKey));return{...item,actionRevision:remote?.actionRevision||'1',status:'ACTIVE'}}).filter(item=>!q||`${item.name} ${item.actionKey}`.toLowerCase().includes(q))}))})
