const emptyDiagram=(name='新建流程模板')=>`<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:agv="http://kunling.com/schema/agv-workflow" id="Definitions_AGV" targetNamespace="http://kunling.com/workflow">
<bpmn:process id="Process_AGV" name="${escapeXml(name)}" isExecutable="true"><bpmn:startEvent id="StartEvent_1" name="开始"><bpmn:outgoing>Flow_1</bpmn:outgoing></bpmn:startEvent><bpmn:serviceTask id="Activity_1" name="移动" agv:actionKey="MOVE" agv:failureStrategy="RETRY_THEN_SUSPEND"><bpmn:incoming>Flow_1</bpmn:incoming><bpmn:outgoing>Flow_2</bpmn:outgoing></bpmn:serviceTask><bpmn:endEvent id="EndEvent_1" name="结束"><bpmn:incoming>Flow_2</bpmn:incoming></bpmn:endEvent><bpmn:sequenceFlow id="Flow_1" sourceRef="StartEvent_1" targetRef="Activity_1"/><bpmn:sequenceFlow id="Flow_2" sourceRef="Activity_1" targetRef="EndEvent_1"/></bpmn:process>
<bpmndi:BPMNDiagram id="BPMNDiagram_1"><bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="Process_AGV"><bpmndi:BPMNShape id="StartEvent_1_di" bpmnElement="StartEvent_1"><dc:Bounds x="160" y="192" width="36" height="36"/></bpmndi:BPMNShape><bpmndi:BPMNShape id="Activity_1_di" bpmnElement="Activity_1"><dc:Bounds x="270" y="170" width="100" height="80"/></bpmndi:BPMNShape><bpmndi:BPMNShape id="EndEvent_1_di" bpmnElement="EndEvent_1"><dc:Bounds x="445" y="192" width="36" height="36"/></bpmndi:BPMNShape><bpmndi:BPMNEdge id="Flow_1_di" bpmnElement="Flow_1"><di:waypoint x="196" y="210"/><di:waypoint x="270" y="210"/></bpmndi:BPMNEdge><bpmndi:BPMNEdge id="Flow_2_di" bpmnElement="Flow_2"><di:waypoint x="370" y="210"/><di:waypoint x="445" y="210"/></bpmndi:BPMNEdge></bpmndi:BPMNPlane></bpmndi:BPMNDiagram></bpmn:definitions>`
const blankMainDiagram=name=>`<?xml version="1.0" encoding="UTF-8"?><bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:agv="http://kunling.com/schema/agv-workflow" id="Definitions_AGV" targetNamespace="http://kunling.com/workflow"><bpmn:process id="Process_AGV" name="${escapeXml(name)}" isExecutable="true"/><bpmndi:BPMNDiagram id="BPMNDiagram_1"><bpmndi:BPMNPlane id="BPMNPlane_1" bpmnElement="Process_AGV"/></bpmndi:BPMNDiagram></bpmn:definitions>`
const blankChildDiagram=name=>`<?xml version="1.0" encoding="UTF-8"?><bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" xmlns:agv="http://kunling.com/schema/agv-workflow" id="Definitions_Child" targetNamespace="http://kunling.com/workflow"><bpmn:process id="Process_Child" name="${escapeXml(name)}" isExecutable="true"/><bpmndi:BPMNDiagram id="BPMNDiagram_Child"><bpmndi:BPMNPlane id="BPMNPlane_Child" bpmnElement="Process_Child"/></bpmndi:BPMNDiagram></bpmn:definitions>`

function normalizeActions(rows){const fallback=[['移动','MOVE'],['单次取料','ARM.PICK'],['单次放料','ARM.PLACE'],['复合取料','ARM.BATCH_PICK'],['复合放料','ARM.BATCH_PLACE'],['协作臂归零','ARM.HOME'],['现场拍照','VISION.CAPTURE'],['自动门','DOOR.OPEN'],['手套箱','GLOVEBOX.RUN'],['贴标机台','LABEL.RUN'],['后处理机台','POST.RUN']].map(([name,actionKey])=>({name,actionKey,actionRevision:'1',status:'ACTIVE'}));return rows?.length?rows.map(r=>({name:r.definition?.displayName||r.displayName||r.actionKey,actionKey:r.actionKey,actionRevision:String(r.revision||''),status:r.status||'ACTIVE'})):fallback}
function selectElement(element){selectedElement.value=element;const b=element?.businessObject;Object.assign(propertyForm,{name:b?.name||'',actionKey:b?.actionKey||'',actionRevision:b?.actionRevision||'',executionParams:b?.executionParams||'',failureStrategy:b?.failureStrategy||'RETRY_THEN_SUSPEND',completionBasis:b?.completionBasis||''})}
function removeDiagramElement(element){if(!element)return;modeler.value.get('modeling').removeElements([element]);modeler.value.get('selection').select(null)}
function startConnection(event,element,side){if(element.outgoing?.some(flow=>flow.type==='bpmn:SequenceFlow'))return;event.stopPropagation();event.preventDefault();pendingSourceSide=side;const x=side==='left'?element.x:element.x+element.width;modeler.value.get('connect').start(event,element,{x,y:element.y+element.height/2})}
function orthogonalWaypoints(connection){
  const source=connection?.source,target=connection?.target
  if(!source||!target)return[]
  const sourceSide=connection.businessObject?.sourceSide||connection._agvSourceSide||'right',targetSide=connection.businessObject?.targetSide||connection._agvTargetSide||'left'
  const sourcePoint={x:sourceSide==='left'?source.x:source.x+source.width,y:source.y+source.height/2}
  const targetPoint={x:targetSide==='left'?target.x:target.x+target.width,y:target.y+target.height/2}
  const clearance=36
  if(sourceSide===targetSide){
    const outerX=sourceSide==='right'
      ?Math.max(sourcePoint.x,targetPoint.x)+clearance
      :Math.min(sourcePoint.x,targetPoint.x)-clearance
    return[sourcePoint,{x:outerX,y:sourcePoint.y},{x:outerX,y:targetPoint.y},targetPoint]
  }
  const sourceExitX=sourcePoint.x+(sourceSide==='left'?-clearance:clearance)
  const targetEntryX=targetPoint.x+(targetSide==='left'?-clearance:clearance)
  const facingWithSpace=Math.abs(sourcePoint.y-targetPoint.y)<1&&(
    (sourceSide==='right'&&targetSide==='left'&&sourcePoint.x<=targetPoint.x)||
    (sourceSide==='left'&&targetSide==='right'&&sourcePoint.x>=targetPoint.x)
  )
  if(facingWithSpace)return[sourcePoint,targetPoint]
  const verticalGap=target.y-(source.y+source.height)
  const reverseVerticalGap=source.y-(target.y+target.height)
  let routeY
  if(verticalGap>=clearance*2)routeY=(source.y+source.height+target.y)/2
  else if(reverseVerticalGap>=clearance*2)routeY=(target.y+target.height+source.y)/2
  else routeY=Math.min(source.y,target.y)-clearance
  const points=[sourcePoint,{x:sourceExitX,y:sourcePoint.y},{x:sourceExitX,y:routeY},{x:targetEntryX,y:routeY},{x:targetEntryX,y:targetPoint.y},targetPoint]
  return points.filter((point,index)=>!index||point.x!==points[index-1].x||point.y!==points[index-1].y)
}
function sameWaypoints(current,next){return current?.length===next.length&&current.every((point,index)=>Math.abs(point.x-next[index].x)<.5&&Math.abs(point.y-next[index].y)<.5)}
function normalizeSequenceFlows(){
  if(!modeler.value)return
  const modeling=modeler.value.get('modeling')
  modeler.value.get('elementRegistry').filter(element=>element.type==='bpmn:SequenceFlow').forEach(connection=>{
    const waypoints=orthogonalWaypoints(connection)
    if(waypoints.length&&!sameWaypoints(connection.waypoints,waypoints))modeling.updateWaypoints(connection,waypoints)
  })
}
function normalizeNodeBounds(){const modeling=modeler.value.get('modeling');modeler.value.get('elementRegistry').filter(element=>['bpmn:StartEvent','bpmn:ServiceTask','bpmn:EndEvent'].includes(element.type)&&(element.width!==180||element.height!==66)).forEach(element=>modeling.resizeShape(element,{x:element.x+(element.width-180)/2,y:element.y+(element.height-66)/2,width:180,height:66}))}
function orderedFlowElements(){const registry=modeler.value.get('elementRegistry'),supported=registry.filter(e=>['bpmn:StartEvent','bpmn:ServiceTask','bpmn:EndEvent'].includes(e.type)),start=supported.find(e=>e.type==='bpmn:StartEvent'),ordered=[],seen=new Set();let current=start;while(current&&!seen.has(current.id)){seen.add(current.id);ordered.push(current);current=current.outgoing?.find(flow=>flow.type==='bpmn:SequenceFlow')?.target}return[...ordered,...supported.filter(element=>!seen.has(element.id))]}
function canvasNodeIcon(element){if(element.type==='bpmn:StartEvent')return'➤';if(element.type==='bpmn:EndEvent')return'♟';return actionGlyph({actionKey:element.businessObject.actionKey})}
function refreshNodeOverlays(){if(!modeler.value)return;const overlays=modeler.value.get('overlays'),canvas=modeler.value.get('canvas'),registry=modeler.value.get('elementRegistry');overlays.clear();registry.filter(e=>e.type!=='label').forEach(element=>canvas.removeMarker(element,'agv-card-node'));registry.filter(e=>e.type==='label').forEach(element=>canvas.removeMarker(element,'agv-card-label'));const nodes=orderedFlowElements(),nodeIds=new Set(nodes.map(element=>element.id));registry.filter(element=>element.type==='label'&&nodeIds.has(element.labelTarget?.id)).forEach(label=>canvas.addMarker(label,'agv-card-label'));nodes.forEach((element,index)=>{canvas.addMarker(element,'agv-card-node');const card=document.createElement('div');card.className=`agv-canvas-node${selectedElement.value?.id===element.id?' selected':''}`;card.dataset.elementId=element.id;const title=document.createElement('strong');title.textContent=`${index+1} · ${element.businessObject.name||element.type.replace('bpmn:','')}`;const type=document.createElement('small');type.textContent=element.type==='bpmn:ServiceTask'?(childMode.value?'子节点':'主节点'):'通用节点';const icon=document.createElement('span');icon.className='agv-canvas-node-icon';icon.textContent=canvasNodeIcon(element);const remove=document.createElement('button');remove.type='button';remove.className='agv-canvas-node-delete';remove.textContent='×';remove.title='删除节点';remove.addEventListener('click',event=>{event.stopPropagation();removeDiagramElement(element)});card.append(title,type,icon,remove);if(element.type==='bpmn:ServiceTask'&&!childMode.value){const child=document.createElement('button');child.type='button';child.className='agv-canvas-node-child';child.textContent='配置子节点 ›';child.addEventListener('click',event=>{event.stopPropagation();openSubflow(element)});card.append(child)}overlays.add(element,{position:{left:(element.width-180)/2,top:(element.height-66)/2},html:card})});const connection=selectedElement.value?.type==='bpmn:SequenceFlow'?selectedElement.value:null;if(connection?.waypoints?.length){const first=connection.waypoints[0],last=connection.waypoints.at(-1),minX=Math.min(...connection.waypoints.map(point=>point.x)),minY=Math.min(...connection.waypoints.map(point=>point.y)),button=document.createElement('button');button.type='button';button.className='agv-connection-delete';button.textContent='×';button.title='删除连线';button.addEventListener('click',event=>{event.stopPropagation();removeDiagramElement(connection)});overlays.add(connection,{position:{left:(first.x+last.x)/2-minX-11,top:(first.y+last.y)/2-minY-11},html:button})}}
function setNodeHover(element,hovered){const card=document.querySelector(`.agv-canvas-node[data-element-id="${element?.id}"]`);card?.classList.toggle('hovered',hovered)}
function moveCardWithShape(event){const shape=event.context?.shape,card=document.querySelector(`.agv-canvas-node[data-element-id="${shape?.id}"]`);if(card){const scale=modeler.value.get('canvas').zoom();card.style.transform=`translate(${event.dx*scale}px,${event.dy*scale}px)`}}
function resetMovingCard(event){const shape=event.context?.shape,card=document.querySelector(`.agv-canvas-node[data-element-id="${shape?.id}"]`);if(card)card.style.transform=''}
function refreshConnectionPorts(){modeler.value.get('elementRegistry').filter(element=>['bpmn:StartEvent','bpmn:ServiceTask','bpmn:EndEvent'].includes(element.type)).forEach(element=>{const card=document.querySelector(`.agv-canvas-node[data-element-id="${element.id}"]`);if(!card||card.querySelector('.agv-node-port'))return;const occupied=element.outgoing?.some(flow=>flow.type==='bpmn:SequenceFlow'),canStart=element.type!=='bpmn:EndEvent';['left','right'].forEach(side=>{const port=document.createElement('button');port.type='button';port.className=`agv-node-port agv-node-port-${side}${occupied?' occupied':''}${canStart?'':' target-only'}`;port.title=canStart?(occupied?'已有后续连线':`从节点${side==='left'?'左':'右'}侧拖出连线`):`结束节点${side==='left'?'左':'右'}侧连线入口`;if(canStart)port.addEventListener('mousedown',event=>startConnection(event,element,side));card.append(port)})})}
function refreshAllOverlays(){refreshNodeOverlays();refreshConnectionPorts()}
function setConnectionTarget(element,active){const card=document.querySelector(`.agv-canvas-node[data-element-id="${element?.id}"]`);card?.classList.toggle('connection-target',active)}
function connectionTargetSide(event,target){const card=document.querySelector(`.agv-canvas-node[data-element-id="${target?.id}"]`),clientX=event.originalEvent?.clientX;if(card&&Number.isFinite(clientX)){const bounds=card.getBoundingClientRect();return clientX<bounds.left+bounds.width/2?'left':'right'}return event.x<target.x+target.width/2?'left':'right'}
function bindEvents(instance){const bus=instance.get('eventBus');bus.on('directEditing.activate.allowed',2000,()=>false);bus.on('selection.changed',({newSelection})=>{selectElement(newSelection[0]||null);queueMicrotask(refreshAllOverlays)});bus.on('commandStack.changed',()=>{diagramRevision.value++;if(!loading.value)dirty.value=true;queueMicrotask(refreshAllOverlays);requestAnimationFrame(refreshAllOverlays)});bus.on('connect.start',()=>canvasHost.value?.classList.add('is-connecting'));bus.on(['connect.cleanup','connect.canceled'],()=>canvasHost.value?.classList.remove('is-connecting'));bus.on('connect.move',800,event=>{const context=event.context,target=context.target||context.hover,source=context.source||context.start;if(!target||!source||!context.canExecute)return;const targetSide=connectionTargetSide(event,target),preview={source,target,_agvSourceSide:pendingSourceSide,_agvTargetSide:targetSide,businessObject:{sourceSide:pendingSourceSide,targetSide}},waypoints=orthogonalWaypoints(preview);instance.get('connectionPreview').drawPreview(context,context.canExecute,{source,target,connectionStart:waypoints[0],connectionEnd:waypoints.at(-1),waypoints,noLayout:true,noCropping:true})});bus.on('connect.end',2000,event=>{const target=event.hover||event.context?.hover;if(target){pendingTargetSide=connectionTargetSide(event,target);event.x=pendingTargetSide==='left'?target.x:target.x+target.width;event.y=target.y+target.height/2}});bus.on(['commandStack.connection.create.postExecuted','commandStack.connection.reconnect.postExecuted'],event=>{const connection=event.context?.connection;if(connection){connection._agvSourceSide=pendingSourceSide;connection._agvTargetSide=pendingTargetSide;connection.businessObject.sourceSide=pendingSourceSide;connection.businessObject.targetSide=pendingTargetSide}queueMicrotask(normalizeSequenceFlows)});bus.on('shape.move.move',moveCardWithShape);bus.on(['shape.move.end','shape.move.cleanup'],event=>{resetMovingCard(event);queueMicrotask(normalizeSequenceFlows)});bus.on('connect.hover',({hover})=>setConnectionTarget(hover,true));bus.on(['connect.out','connect.cleanup'],({hover,context})=>setConnectionTarget(hover||context?.hover,false));bus.on('element.hover',({element})=>setNodeHover(element,true));bus.on('element.out',({element})=>setNodeHover(element,false));bus.on('element.dblclick',({element})=>{if(!childMode.value&&element?.type==='bpmn:ServiceTask')openSubflow(element)})}
function updateSelectedProperty(key,value){if(selectedElement.value)modeler.value.get('modeling').updateProperties(selectedElement.value,{[key]:value||undefined})}
function actionGlyph(action){const key=String(action?.actionKey||'').toUpperCase();if(key.includes('VISION'))return'▣';if(key.includes('HOME'))return'↻';if(key.includes('PICK'))return'↑';if(key.includes('PLACE'))return'↓';if(key.includes('MOVE')||key.includes('MOTION'))return'✣';if(key.includes('GRIP'))return'⑂';if(key.includes('DOOR'))return'⇥';if(key.includes('LABEL'))return'▤';if(key.includes('GLOVE'))return'▧';return'◆'}
function createActionShape(action){const i=modeler.value,bo=i.get('bpmnFactory').create('bpmn:ServiceTask',{name:action.name,actionKey:action.actionKey,actionRevision:action.actionRevision,failureStrategy:'RETRY_THEN_SUSPEND'});return i.get('elementFactory').createShape({type:'bpmn:ServiceTask',businessObject:bo,width:180,height:66})}
function dragAction(event,action){if(event.button!=null&&event.button!==0)return;event.preventDefault();modeler.value.get('create').start(event,createActionShape(action))}
function addAction(){}
function eventExists(type){diagramRevision.value;return Boolean(modeler.value?.get('elementRegistry').filter(element=>element.type===type).length)}
function handleActionMouseDown(event){const button=event.target.closest?.('.workflow-editor-page .action-card:not(:disabled)');const key=button?.querySelector('small')?.textContent?.trim();if(!key)return;const action=allPaletteActions.value.find(item=>item.actionKey===key);if(action)dragAction(event,action)}
function refreshActionIcons(){nextTick(()=>document.querySelectorAll('.workflow-editor-page .action-card:not(.event-actions .action-card)').forEach(button=>{const key=button.querySelector('small')?.textContent?.trim(),action=allPaletteActions.value.find(item=>item.actionKey===key),icon=button.querySelector('.action-icon');if(action&&icon)icon.textContent=actionGlyph(action)}))}
function dragEvent(event,type,name){if(event.button!=null&&event.button!==0)return;const i=modeler.value;if(i.get('elementRegistry').filter(element=>element.type===type).length)return ElMessage.warning(`当前画布只能有一个${name}节点`);event.preventDefault();const bo=i.get('bpmnFactory').create(type,{name}),shape=i.get('elementFactory').createShape({type,businessObject:bo,width:180,height:66});i.get('create').start(event,shape)}
function addEvent(type,name){const i=modeler.value,canvas=i.get('canvas'),factory=i.get('elementFactory'),modeling=i.get('modeling'),view=canvas.viewbox();if(i.get('elementRegistry').filter(e=>e.type===type).length)return ElMessage.warning(`当前画布只能有一个${name}节点`);const shape=factory.createShape({type,width:180,height:66});modeling.createShape(shape,{x:view.x+view.width/2+(type==='bpmn:StartEvent'?-120:120),y:view.y+view.height/2},canvas.getRootElement());modeling.updateProperties(shape,{name});i.get('selection').select(shape)}
function zoom(value){const c=modeler.value?.get('canvas');if(!c)return;if(value==='fit')c.zoom('fit-viewport');else c.zoom(Math.min(2,Math.max(.35,c.zoom()+value)));zoomLevel.value=Math.round(c.zoom()*100)}
async function importDiagram(xml){await modeler.value.importXML(xml);normalizeNodeBounds();normalizeSequenceFlows();await nextTick();modeler.value.get('canvas').zoom('fit-viewport');zoomLevel.value=Math.round(modeler.value.get('canvas').zoom()*100);refreshAllOverlays();refreshActionIcons();dirty.value=false}
async function openSubflow(element){if(childMode.value||!element)return;const{xml}=await modeler.value.saveXML({format:true});mainXmlCache.value=xml;childParentId.value=element.id;childParentName.value=element.businessObject.name||element.id;const childXml=element.businessObject.subProcessXml||blankChildDiagram(`${childParentName.value} 子流程`);childMode.value=true;selectedElement.value=null;await importDiagram(childXml);ElMessage.info(`已进入 ${childParentName.value} 的子节点配置`)}
async function returnToMain(saveChild=false){if(!childMode.value)return;let childXml='';if(saveChild)({xml:childXml}=await modeler.value.saveXML({format:true}));const parentId=childParentId.value,parentName=childParentName.value;childMode.value=false;await importDiagram(mainXmlCache.value);const parent=modeler.value.get('elementRegistry').get(parentId);if(saveChild&&parent){modeler.value.get('modeling').updateProperties(parent,{subProcessXml:childXml});dirty.value=true;ElMessage.success(`${parentName} 的子流程已保存`)}else ElMessage.info('已返回主流程');if(parent)modeler.value.get('selection').select(parent);childParentId.value='';childParentName.value=''}

async function migrateLegacy(data){await importDiagram(emptyDiagram(meta.templateName));if(!Array.isArray(data?.nodes)||!data.nodes.length)return;const i=modeler.value,registry=i.get('elementRegistry'),modeling=i.get('modeling'),canvas=i.get('canvas'),factory=i.get('elementFactory'),bpmnFactory=i.get('bpmnFactory'),root=canvas.getRootElement();modeling.removeElements(registry.filter(e=>e.parent&&e.type!=='label'));const map=new Map();for(const n of data.nodes){const type=n.name==='开始'?'bpmn:StartEvent':n.name==='结束'?'bpmn:EndEvent':'bpmn:ServiceTask';const bo=bpmnFactory.create(type,{name:n.name,...(type==='bpmn:ServiceTask'?{actionKey:n.actionKey||n.actionType||'CUSTOM',actionRevision:String(n.actionRevision||''),executionParams:n.parameterText||n.executionParams?.raw||'',failureStrategy:n.failureStrategy||'RETRY_THEN_SUSPEND',completionBasis:n.completionBasis||''}:{})});const shape=factory.createShape({type,businessObject:bo});modeling.createShape(shape,{x:Number(n.x??n.position?.x??80)+(type.includes('Event')?18:50),y:Number(n.y??n.position?.y??100)+(type.includes('Event')?18:40)},root);map.set(String(n.id),shape)}for(const line of data.connections||[]){const source=map.get(String(line.from)),target=map.get(String(line.to));if(source&&target)modeling.connect(source,target,{type:'bpmn:SequenceFlow'})}canvas.zoom('fit-viewport');dirty.value=true;ElMessage.info('旧版画板已转换为 BPMN 2.0，保存后完成迁移')}

async function load(){loading.value=true;try{try{actions.value=normalizeActions(await getActions())}catch(error){actions.value=normalizeActions([]);ElMessage.warning(`动作清单加载失败，使用内置动作：${error.message}`)}if(!editingId){meta.templateNumber=`TPL-${Date.now().toString().slice(-8)}`;meta.templateName='新建流程模板';await importDiagram(blankMainDiagram(meta.templateName));return}const d=await getWorkflow(editingId);Object.assign(meta,{id:d.id,templateNumber:d.templateNumber||String(editingId),templateName:d.templateName||'',applicableObject:d.applicableObject||'复合机器人',status:d.status==='ENABLED'||d.deployedVersion?'已启用 · 修改后转草稿':'草稿'});const editorData=typeof d.editorData==='string'?JSON.parse(d.editorData):d.editorData||{};if(d.bpmnXml?.includes('BPMNDiagram'))await importDiagram(d.bpmnXml);else await migrateLegacy(editorData)}catch(error){ElMessage.error(`模板加载失败：${error.message}`);await importDiagram(emptyDiagram(meta.templateName||'流程模板'))}finally{loading.value=false}}
function validateDiagram(){const es=modeler.value.get('elementRegistry').filter(e=>e.businessObject&&e.type!=='label');if(es.filter(e=>e.type==='bpmn:StartEvent').length!==1||es.filter(e=>e.type==='bpmn:EndEvent').length!==1)return'流程必须且只能包含一个开始事件和一个结束事件';const missing=es.find(e=>e.type==='bpmn:ServiceTask'&&!e.businessObject.actionKey);if(missing)return`服务任务“${missing.businessObject.name||missing.id}”缺少动作编码`;return''}
async function save(){if(childMode.value)await returnToMain(true);if(!meta.templateName.trim())return ElMessage.warning('请填写模板名称');const error=validateDiagram();if(error)return ElMessage.warning(error);saving.value=true;try{const{xml}=await modeler.value.saveXML({format:true});const result=await saveWorkflow({...meta.id&&{id:meta.id},templateName:meta.templateName.trim(),applicableObject:meta.applicableObject,bpmnXml:xml,editorData:{format:'bpmn-js',version:1}});meta.id=result?.id||meta.id;meta.templateNumber=result?.templateNumber||meta.templateNumber;meta.status=result?.status==='ENABLED'?'已启用 · 修改后转草稿':'草稿';dirty.value=false;ElMessage.success('BPMN 流程模板已保存')}catch(error){ElMessage.error(`保存失败：${error.message}`)}finally{saving.value=false}}
onMounted(async()=>{document.addEventListener('mousedown',handleActionMouseDown,true);modeler.value=new BpmnModeler({container:canvasHost.value,moddleExtensions:{agv:agvModdle}});bindEvents(modeler.value);await load();refreshActionIcons()})
onBeforeUnmount(()=>{document.removeEventListener('mousedown',handleActionMouseDown,true);modeler.value?.destroy()})
</script>

<template><div class="page-view workflow-editor-page"><PageHeader class="page-head" title="流程模板" description="基于 BPMN 2.0 标准编排 AGV 动作、事件、网关和顺序流"><div class="header-actions"><span v-if="dirty" class="dirty-indicator">有未保存修改</span><router-link class="secondary-button" to="/workflows/templates">返回模板列表</router-link><button class="primary-button" type="button" :disabled="saving||loading" @click="save">{{saving?'保存中…':'保存 BPMN'}}</button></div></PageHeader>
<main class="editor-page-canvas"><section class="meta-panel"><div class="meta-heading"><div><h2>{{editingId?`编辑模板 · ${meta.templateNumber}`:'新建 BPMN 模板'}}</h2><p>保存标准 BPMN XML 与 BPMN DI，可被 Flowable 和其他 BPMN 工具读取。</p></div><span class="status-pill">{{meta.status}}</span></div><div class="meta-fields"><label><span>模板编号</span><input v-model="meta.templateNumber" @input="dirty=true"></label><label><span>模板名称</span><input v-model="meta.templateName" @input="dirty=true"></label><label><span>适用对象</span><select v-model="meta.applicableObject" @change="dirty=true"><option>复合机器人</option><option>贴标工作站</option><option>手套箱</option><option>后处理机台</option><option>检测工作站</option></select></label></div></section>
<section class="canvas-section"><div class="canvas-section-heading"><h2>Canvas 动作组合画布</h2><p>从左侧动作清单拖入节点；点击主节点上的“配置子节点”进入独立子流程。</p></div><div class="modeler-shell"><aside class="action-panel"><div class="panel-title"><h3>动作清单</h3><span>⌃</span></div><p>根据主节点或子节点选择自动切换</p><input v-if="!childMode" v-model="actionKeyword" class="action-search" placeholder="搜索动作名称或编码"><div class="action-group-label">通用节点</div><div class="action-list event-actions"><button type="button" class="action-card event-card" :disabled="eventExists('bpmn:StartEvent')" @mousedown="dragEvent($event,'bpmn:StartEvent','开始')"><span class="event-symbol start-symbol">➤</span><strong>开始</strong></button><button type="button" class="action-card event-card" :disabled="eventExists('bpmn:EndEvent')" @mousedown="dragEvent($event,'bpmn:EndEvent','结束')"><span class="event-symbol end-symbol">♟</span><strong>结束</strong></button></div><template v-for="group in paletteGroups" :key="group.label"><div v-if="group.items.length" class="action-group-label">{{group.label}}</div><div v-if="group.items.length" class="action-list"><button v-for="action in group.items" :key="action.actionKey" type="button" class="action-card" @click="addAction(action)"><span class="action-icon">◆</span><span><strong>{{action.name}}</strong><small>{{action.actionKey}}</small></span></button></div></template></aside>
<div :class="['canvas-column',{'with-toolbar':childMode}]"><div v-if="childMode" class="canvas-toolbar"><button class="back-main" type="button" @click="returnToMain(false)">← 返回主节点：{{childParentName}}</button><button class="save-child" type="button" @click="returnToMain(true)">保存并返回</button></div><div ref="canvasHost" :class="['bpmn-canvas',{'child-canvas':childMode}]"><div v-if="!childMode" class="floating-zoom"><button type="button" title="适应画布" @click="zoom('fit')">⛶</button><button type="button" title="缩小" @click="zoom(-.1)">−</button><span>{{zoomLevel}}%</span><button type="button" title="放大" @click="zoom(.1)">＋</button></div><div v-if="loading" class="loading-mask">正在加载 BPMN 模型…</div></div></div>
<aside class="properties-panel"><div class="panel-title"><h3>节点属性</h3><span>⌃</span></div><p class="property-subtitle">根据主节点或子节点选择自动切换</p><p v-if="!selectedElement" class="empty-properties">请选择画板中的节点</p><template v-else><div class="element-kind"><span>当前节点：{{propertyForm.name||selectedType.replace('bpmn:','')}}</span><small>{{selectedElement.id}}</small></div><label class="property-field"><span>节点名称</span><input v-model="propertyForm.name" disabled></label><label class="property-field"><span>节点分类</span><input :value="isActionTask?(childMode?'子节点':'AGV 节点'):'通用节点'" disabled></label><template v-if="isActionTask"><label class="property-field"><span>执行参数</span><textarea v-model="propertyForm.executionParams" rows="4" placeholder="参数待确认" @input="updateSelectedProperty('executionParams',propertyForm.executionParams)"></textarea></label><label class="property-field"><span>失败策略</span><select v-model="propertyForm.failureStrategy" @change="updateSelectedProperty('failureStrategy',propertyForm.failureStrategy)"><option value="RETRY_THEN_SUSPEND">按策略重试后挂起</option><option value="SUSPEND">立即挂起</option><option value="SKIP">跳过并记录</option></select></label><label class="property-field"><span>完成依据</span><textarea v-model="propertyForm.completionBasis" rows="3" placeholder="设备反馈 + 状态校验，待技术确认" @input="updateSelectedProperty('completionBasis',propertyForm.completionBasis)"></textarea></label></template><div v-else class="standard-note">标准 BPMN 事件或网关，可通过画板快捷菜单连接、替换或删除。</div></template></aside></div></section></main></div></template>

